-- Przywraca stronę www/FB z menu na pinach, które stoją w tym samym miejscu co import OSM.
-- Nie nadpisuje adresu, który już jest wpisany.

update public.pins
set website = substring(description from 'https?://[^[:space:]]+')
where (website is null or btrim(website) = '')
  and description ~* 'https?://';

